(106, 'widget_block', 'a:24:{i:2;a:1:{s:7:\"content\";s:19:\"<!-- wp:search /-->\";}i:3;a:1:{s:7:\"content\";s:185:\"<!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">最新發表</h2>\n<!-- /wp:heading -->\n\n<!-- wp:latest-posts /--></div>\n<!-- /wp:group -->\";}i:4;a:1:{s:7:\"content\";s:252:\"<!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">留言處</h2>\n<!-- /wp:heading -->\n\n<!-- wp:latest-comments {\"displayAvatar\":false,\"displayDate\":false,\"displayExcerpt\":false} /--></div>\n<!-- /wp:group -->\";}i:5;a:1:{s:7:\"content\";s:181:\"<!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">文章列表</h2>\n<!-- /wp:heading -->\n\n<!-- wp:archives /--></div>\n<!-- /wp:group -->\";}i:6;a:1:{s:7:\"content\";s:214:\"<!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">分類</h2>\n<!-- /wp:heading -->\n\n<!-- wp:categories {\"metadata\":{\"name\":\"尚未歸類\"}} /--></div>\n<!-- /wp:group -->\";}s:12:\"_multiwidget\";i:1;i:9;a:1:{s:7:\"content\";s:23:\"<!-- wp:categories /-->\";}i:10;a:1:{s:7:\"content\";s:22:\"<!-- wp:tag-cloud /-->\";}i:7;a:1:{s:7:\"content\";s:45:\"<!-- wp:mailchimp-for-wp/form {\"id\":924} /-->\";}i:12;a:1:{s:7:\"content\";s:375:\"<!-- wp:image {\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image\"><a href=\"https://wp-royal-themes.com/themes/item-ashe-free/?ref=demo-ashe-free-alt-widgets-downlad/?ref=ashe-demo-import-xml/#download\"><img src=\"https://ashebarddemoimports.kinsta.cloud/ashe-demo-import/wp-content/uploads/sites/4/2022/08/banner_new_1.jpg\" alt=\"\"/></a></figure>\n<!-- /wp:image -->\";}i:13;a:1:{s:7:\"content\";s:23:\"<!-- wp:categories /-->\";}i:14;a:1:{s:7:\"content\";s:201:\"<!-- wp:image {\"id\":931} -->\n<figure class=\"wp-block-image\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/與高地照.jpg\" alt=\"\" class=\"wp-image-931\"/></figure>\n<!-- /wp:image -->\";}i:15;a:1:{s:7:\"content\";s:107:\"<!-- wp:heading {\"level\":6,\"align\":\"center\"} -->\n<h6 class=\"wp-block-heading\">琪</h6>\n<!-- /wp:heading -->\";}i:16;a:1:{s:7:\"content\";s:257:\"<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">台灣高雄人，目前與先生和一隻貓仔定居英國威爾斯。喜歡閱讀、創作，感受美。享受邊工作邊旅行，邊生活邊修行。</p>\n<!-- /wp:paragraph -->\";}i:23;a:1:{s:7:\"content\";s:311:\"<!-- wp:file {\"id\":931,\"href\":\"http://localhost/chi-website/wp-content/uploads/2025/03/與高地照.jpg\"} -->\n<div class=\"wp-block-file\"><a href=\"http://localhost/chi-website/wp-content/uploads/2025/03/與高地照.jpg\" class=\"wp-block-file__button wp-element-button\" download>下載</a></div>\n<!-- /wp:file -->\";}i:26;a:1:{s:7:\"content\";s:413:\"<!-- wp:gallery {\"linkTo\":\"none\",\"sizeSlug\":\"full\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><!-- wp:image {\"id\":30,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/大頭照.jpg\" alt=\"\" class=\"wp-image-30\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\";}i:28;a:1:{s:7:\"content\";s:255:\"<!-- wp:image {\"id\":1097,\"sizeSlug\":\"full\",\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/大頭照.jpg\" alt=\"\" class=\"wp-image-1097\"/></figure>\n<!-- /wp:image -->\";}i:29;a:1:{s:7:\"content\";s:113:\"<!-- wp:heading {\"level\":6,\"align\":\"center\"} -->\n<h6 class=\"wp-block-heading\">關於琪</h6>\n<!-- /wp:heading -->\";}i:30;a:1:{s:7:\"content\";s:233:\"<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">台灣高雄人，目前與老公和貓仔定居英國威爾斯。喜歡閱讀、創作，邊工作邊旅行，邊生活邊修行。</p>\n<!-- /wp:paragraph -->\";}i:31;a:1:{s:7:\"content\";s:175:\"<!-- wp:widget-group -->\n<h2 class=\"widget-title\"></h2><div class=\"wp-widget-group__inner-blocks\"><!-- wp:mailchimp-for-wp/form {\"id\":924} /--></div>\n<!-- /wp:widget-group -->\";}i:32;a:1:{s:7:\"content\";s:375:\"<!-- wp:image {\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image\"><a href=\"https://wp-royal-themes.com/themes/item-ashe-free/?ref=demo-ashe-free-alt-widgets-downlad/?ref=ashe-demo-import-xml/#download\"><img src=\"https://ashebarddemoimports.kinsta.cloud/ashe-demo-import/wp-content/uploads/sites/4/2022/08/banner_new_1.jpg\" alt=\"\"/></a></figure>\n<!-- /wp:image -->\";}i:33;a:1:{s:7:\"content\";s:87:\"<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">廠商廣告</h2>\n<!-- /wp:heading -->\";}i:34;a:1:{s:7:\"content\";s:335:\"<!-- wp:image {\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image\"><a href=\"https://wp-royal-themes.com/themes/item-ashe-free/?ref=ashe-demo-import-xml/#download\"><img src=\"https://ashebarddemoimports.kinsta.cloud/ashe-demo-import/wp-content/uploads/sites/4/2022/08/banner_new_1.png\" alt=\"\"/></a></figure>\n<!-- /wp:image -->\";}i:35;a:1:{s:7:\"content\";s:153:\"<!-- wp:paragraph -->\n<p>Awesome and completely free WordPress WooCommerce themes to take your Blog website to the next level.</p>\n<!-- /wp:paragraph -->\";}}', 'on'),
