(4, 0, '2025-02-27 11:00:02', '2025-02-27 11:00:02', '<!-- wp:navigation-submenu {\"label\":\"威爾斯自由行\",\"type\":\"page\",\"id\":29,\"url\":\"http://localhost/chi-website/%E9%97%9C%E6%96%BC%E5%B0%8F%E7%90%AA/\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:navigation-submenu {\"label\":\"英國自由行\",\"url\":\"%E8%8B%B1%E6%A0%BC%E8%98%AD%E8%87%AA%E7%94%B1%E8%A1%8C\",\"kind\":\"custom\"} -->\n<!-- wp:navigation-link {\"label\":\"英國火車當日票優點\",\"type\":\"post\",\"id\":101,\"url\":\"http://localhost/chi-website/2025/03/10/%E8%8B%B1%E5%9C%8B%E7%81%AB%E8%BB%8A%E7%95%B6%E6%97%A5%E7%A5%A8%E5%84%AA%E9%BB%9E/\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"普利茅斯 – The Box 博物館\",\"type\":\"post\",\"id\":38,\"url\":\"http://localhost/chi-website/2025/02/27/%E8%8B%B1%E5%9C%8B%E6%99%AE%E5%88%A9%E8%8C%85%E6%96%AF%E7%9A%84%E5%8D%9A%E7%89%A9%E9%A4%A8%EF%BC%8Dthe-box/\",\"kind\":\"post-type\"} /-->\n<!-- /wp:navigation-submenu -->\n\n<!-- wp:navigation-submenu {\"label\":\"義大利自由行\",\"type\":\"tag\",\"id\":5,\"url\":\"http://localhost/chi-website/tag/%E7%BE%A9%E5%A4%A7%E5%88%A9%E8%87%AA%E7%94%B1%E8%A1%8C/\",\"kind\":\"taxonomy\"} -->\n<!-- wp:navigation-link {\"label\":\"威尼斯－佛圖尼博物館 （Museo Fortuny）\",\"type\":\"post\",\"id\":5,\"url\":\"http://localhost/chi-website/2025/02/27/%E5%A8%81%E5%B0%BC%E6%96%AF%EF%BC%8D%E4%BD%9B%E5%9C%96%E5%B0%BC%E5%8D%9A%E7%89%A9%E9%A4%A8-%EF%BC%88museo-fortuny%EF%BC%89/\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"內基·坎皮格里奧別墅 （Villa Necchi Campiglio）\",\"type\":\"post\",\"id\":107,\"url\":\"http://localhost/chi-website/2025/03/10/%E5%85%A7%E5%9F%BA%C2%B7%E5%9D%8E%E7%9A%AE%E6%A0%BC%E9%87%8C%E5%A5%A7%E5%88%A5%E5%A2%85-%EF%BC%88villa-necchi-campiglio%EF%BC%89/\",\"kind\":\"post-type\"} /-->\n<!-- /wp:navigation-submenu -->\n\n<!-- wp:navigation-submenu {\"label\":\"亞洲自由行\",\"url\":\"%E6%AD%90%E6%B4%B2%E8%87%AA%E7%94%B1%E8%A1%8C\",\"kind\":\"custom\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"旅遊規劃\",\"type\":\"page\",\"id\":110,\"url\":\"http://localhost/chi-website/?page_id=110\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"關於琪\",\"type\":\"page\",\"id\":29,\"url\":\"http://localhost/chi-website/%e9%97%9c%e6%96%bc%e5%b0%8f%e7%90%aa/\",\"kind\":\"post-type\"} /-->', 'Navigation', '', 'publish', 'closed', 'closed', '', 'navigation', '', '', '2025-03-10 20:35:06', '2025-03-10 20:35:06', '', 0, 'http://localhost/chi-website/2025/02/27/navigation/', 0, 'wp_navigation', '', 0),
(5, 1, '2025-02-27 13:26:46', '2025-02-27 13:26:46', '<!-- wp:paragraph -->\n<p>在威尼斯的時候，參觀了這間「佛圖尼博物館 （Museo Fortuny）」，因為受到建築本身空間規劃的吸引，博物館前身就是藝術家佛圖尼（Mariano Fortuny）本人的住宅，裡頭有他的畫室、織物研究室等，陳列許多畫作、織料和雕塑。<br>而在一樓的冬令花園（The Winter Garden）房，幾面牆上滿滿的壁畫，讓我聯想到毛姆寫的《月亮與六便士》裡最後藝術家的鉅作，有種發自內心的感動。<br>最後還有一個令人意想不到的驚喜，在參觀動線的尾端，有一座迴廊，細緻的工藝搭配精心的照明，當我發現它是由「瓦愣紙」雕築而成時，我驚嘆地重新來回走了好幾遍，想看清楚每個被我忽略的小細節。<br>推薦給要去威尼斯旅行的朋友，這間獨樹一格的博物館。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":21,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/IMG_99421.jpg\" alt=\"\" class=\"wp-image-21\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":20,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/IMG_99351.jpg\" alt=\"\" class=\"wp-image-20\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":19,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/IMG_99341-1.jpg\" alt=\"\" class=\"wp-image-19\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":22,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/IMG_99321.jpg\" alt=\"\" class=\"wp-image-22\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":23,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/IMG_99471.jpg\" alt=\"\" class=\"wp-image-23\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":24,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/IMG_99511.jpg\" alt=\"\" class=\"wp-image-24\"/></figure>\n<!-- /wp:image -->', '威尼斯－佛圖尼博物館 （Museo Fortuny）', '', 'publish', 'open', 'open', '', '%e5%a8%81%e5%b0%bc%e6%96%af%ef%bc%8d%e4%bd%9b%e5%9c%96%e5%b0%bc%e5%8d%9a%e7%89%a9%e9%a4%a8-%ef%bc%88museo-fortuny%ef%bc%89', '', '', '2025-02-27 13:26:46', '2025-02-27 13:26:46', '', 0, 'http://localhost/chi-website/?p=5', 0, 'post', '', 0),
