></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|20\"}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}},\"fontSize\":\"large\"} -->\n<h3 class=\"wp-block-heading has-large-font-size\" style=\"font-style:normal;font-weight:500\">美國</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\"><a href=\"#\">獨立書店</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|20\"}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}},\"fontSize\":\"large\"} -->\n<h3 class=\"wp-block-heading has-large-font-size\" style=\"font-style:normal;font-weight:500\">英國</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\"><a href=\"#\">獨立書店</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"blockGap\":\"var:preset|spacing|50\"}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50)\"><!-- wp:heading {\"fontSize\":\"x-large\"} -->\n<h2 class=\"wp-block-heading has-x-large-font-size\">常見問題集</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"border\":{\"top\":{\"color\":\"var:preset|color|accent-6\",\"width\":\"1px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\" style=\"border-top-color:var(--wp--preset--color--accent-6);border-top-width:1px;padding-top:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">《故事輯錄》的內容為何？</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>這本精美的合輯展示捕捉了不同時代及文化精髓的相片，並反映了每位藝術家的獨特風格及視角。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"border\":{\"top\":{\"color\":\"var:preset|color|accent-6\",\"width\":\"1px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\" style=\"border-top-color:var(--wp--preset--color--accent-6);border-top-width:1px;padding-top:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">《故事輯錄》的售價為何？</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>這本精美的合輯展示捕捉了不同時代及文化精髓的相片，並反映了每位藝術家的獨特風格及視角。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"border\":{\"top\":{\"color\":\"var:preset|color|accent-6\",\"width\":\"1px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\" style=\"border-top-color:var(--wp--preset--color--accent-6);border-top-width:1px;padding-top:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">《故事輯錄》的發售日期為何？</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>這本精美的合輯展示捕捉了不同時代及文化精髓的相片，並反映了每位藝術家的獨特風格及視角。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"border\":{\"top\":{\"color\":\"var:preset|color|accent-6\",\"width\":\"1px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\" style=\"border-top-color:var(--wp--preset--color--accent-6);border-top-width:1px;padding-top:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">是否會發售作者簽名版？</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>這本精美的合輯展示捕捉了不同時代及文化精髓的相片，並反映了每位藝術家的獨特風格及視角。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"aside\",\"align\":\"full\",\"className\":\"is-style-section-3\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"dimensions\":{\"minHeight\":\"\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"800px\"}} -->\n<aside class=\"wp-block-group alignfull is-style-section-3\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"360px\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\" style=\"min-height:360px;margin-top:0;margin-bottom:0\"><!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"xx-large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-xx-large-font-size\">註冊以獲得每日故事選輯</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"is-style-text-subtitle\"} -->\n<p class=\"has-text-align-center is-style-text-subtitle\">獲得以歷史照片為特色的精彩瞬間照片集。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"20px\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"textAlign\":\"center\"} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-center wp-element-button\">訂閱</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></aside>\n<!-- /wp:group -->', 'Marcus的書', '', 'inherit', 'closed', 'closed', '', '89-revision-v1', '', '', '2025-03-10 19:47:39', '2025-03-10 19:47:39', '', 89, 'http://localhost/chi-website/?p=91', 0, 'revision', '', 0),
(94, 1, '2025-03-10 19:50:24', '0000-00-00 00:00:00', '<!-- wp:image {\"id\":95,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/美術老師沒教的藝術欣賞課.jpg\" alt=\"\" class=\"wp-image-95\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>這個課程是我和馬先生一同創作的心血結晶，緣起是他2018-19年在台灣的時候寫了一本書，叫做《藝術並非十一種玩意兒——藉由破除迷思進而揭露藝術的真正價值及重要性 （Eleven Things That Art is Not—— debunking the misconceptions to reveal the true value and importance of art）》，2020年上架到亞馬遜網站。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>這本書，我讀完後深受感動，於是自告奮勇將它翻譯成中文，想讓對藝術有興趣的台灣人也可以受惠。這裡補充一下我的相關背景，我畢業於東吳英文系，畢業之後斜槓口譯、筆譯與編輯工作至今超過15年，書面處理過大約325萬字。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>總之，緣份之下接到一位好友邀請，得知「Joy to Know 就去學」提供了我們一個分享的平台，於是依照其課程架構，擷取了書中部分內容，錄製成一個大約50分鐘的線上講座，分為五堂課、一堂10分鐘左右，希望藉由知識的分享，讓有興趣的人能夠更瞭解藝術。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>今天跟大家分享，提供給就去學知識平台的其中一段書中內容。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>為什麼許多藝術家的作品名為《無題》呢？</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>西元 1550 年，喬治．瓦薩里獻給佛羅倫斯公爵的《藝苑名人傳》，是一部共有十冊的藝術史巨作，除了詳細記述了藝術家們的生活，也討論了藝術家的作品和發表了評論，值得注意的是，他使用內容、地點或作品特徵的方式來指稱作品，而非作品的名稱。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>這是因為，在當時，作品根本沒有名稱。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>從古典樂時期流傳下來的傳統是，作曲家只為他所編寫的曲目標上數字以供區分。大名鼎鼎的作品，達文西的《蒙娜麗莎》、貝多芬的《月光奏鳴曲》，創作者本人都不是這麼命名，這些名稱皆為其他人後來冠上。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>事實上，為作品命名完全是現代才有的事，不確定從何時何處開始，直到今日，藝術品的名字，仍然相當普遍地由藝廊老闆、館長、評論家或贊助商來定，而非藝術家本人。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>追尋這項發展背後可能的原因，我們從惠斯勒最有名的畫作《惠斯勒的母親》中可一窺端倪，至少，它後來的名稱為此。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>在 1871 年，倫敦皇家藝術學院本來要拒絕展出這幅作品，因為當時呈交的名稱為「灰與黑的排列組合」。普羅大眾和學院成員都想要一個更具描述性的名稱，所以惠斯勒為了展覽被迫取了一個副標題「藝術家母親之肖像」。由此，逐漸演變成後來為人所知的稱謂。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>這讓人不禁疑問，名稱真的如此必要嗎？</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>如果畫家畫了一隻貓，把這幅畫稱作《貓》，好像沒什麼意義。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>惠斯勒在 1890 年寫出了《灰與黑的排列組合》事件帶給他的困惑：「對我來說，那幅我母親的畫作非常有意思；但對大眾而言，他們幹嘛要、也怎麼會在乎那幅肖像畫的是誰？」</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>我們常常在美術館或博物館裡看到一群人，熱切地看著聽著導覽人員，甚至比他們看展覽品的時間還多。展覽廳可能空蕩蕩，但藝術家訪談的影片總是圍繞著一群觀眾。當被問及何以如此，常常得到的回答是，如果不知道作品名稱或相關資料擔心會看不懂。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>然而，藝術家們已經不知說過多少次，談論藝術是沒有用的：</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>「畫作中最有價值的部分，正是無法以言語描述出來的部分。」——喬治．布拉克</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>「試著解釋一幅畫的人，通常都挑錯重點了。」——巴勃羅．畢卡索</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>「如果你講的出來，幹嘛還要畫？」、「談論一幅畫是沒有用的——一個人永遠講不出來，他只能在周圍繞圈圈。」——法蘭西斯．培根</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>一件藝術品能夠獨當一面；它不需要任何解釋。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>況且，當你在處理藝術這個主題的時候，你在處理的是高於語言的媒介。我們在談的不只是繪畫：「在 20 世紀以前，大家都認為作家已經把他想說的全都寫在他的作品裡了。」——約翰．厄普代克</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>一段純粹的音樂是抽象的。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>要說一個人能夠口頭詮釋它的意思，是很奇怪的概念。要為這些音符組合加上一個名字局限在一個代表，是更奇怪的一件事，因為之前沒有名字時，反而擁有天馬行空的無限自由。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>下次，當你去看一幅畫作時，不要顧著拍照，不要和朋友聊天，不要戴上耳機或做任何事情，試著保持安靜、靜止，真正地去看那幅畫，只要去體驗、感受它，花點時間。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>如果它帶你到了某種境界，讓它帶領，看看你是否喜歡，或是否覺得有趣。強烈的藝術體驗，可能會產生一種「浩瀚的感受」——彷彿「與一切合而為一」。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>藝術家能帶領人們啟航——不只是將人們從泥濘中扶起，而是帶領他們航向星際。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><img height=\"16\" width=\"16\" alt=\"👉\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t51/1/16/1f449.png\">如果你對藝術這個主題也有興趣，歡迎來上【美術老師沒教的藝術欣賞課】線上音頻課程。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><img height=\"16\" width=\"16\" alt=\"🚩\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tc6/1/16/1f6a9.png\">免費試聽第一堂：<a href=\"https://reurl.cc/VLgWxN?fbclid=IwZXh0bgNhZW0CMTAAAR0sibRX4ZlHv-aepuZ9GxctKEibyzChOhKFgMiBnk1DmCJCwYA8SYlSP54_aem_9jgQd42k8BNr3-oNu7HM7w\" rel=\"noreferrer noopener\" target=\"_blank\">https://reurl.cc/VLgWxN</a></p>\n<!-- /wp:paragraph -->', '【美術老師沒教的藝術欣賞課】線上音頻課程', '', 'draft', 'open', 'open', '', '', '', '', '2025-03-10 19:50:24', '2025-03-10 19:50:24', '', 0, 'http://localhost/chi-website/?p=94', 0, 'post', '', 0),
(95, 1, '2025-03-10 19:50:12', '2025-03-10 19:50:12', '', '美術老師沒教的藝術欣賞課', '', 'inherit', 'open', 'closed', '', '%e7%be%8e%e8%a1%93%e8%80%81%e5%b8%ab%e6%b2%92%e6%95%99%e7%9a%84%e8%97%9d%e8%a1%93%e6%ac%a3%e8%b3%9e%e8%aa%b2', '', '', '2025-03-10 19:50:12', '2025-03-10 19:50:12', '', 94, 'http://localhost/chi-website/wp-content/uploads/2025/03/美術老師沒教的藝術欣賞課.jpg', 0, 'attachment', 'image/jpeg', 0),
(96, 1, '2025-03-10 19:50:24', '2025-03-10 19:50:24', '<!-- wp:image {\"id\":95,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/美術老師沒教的藝術欣賞課.jpg\" alt=\"\" class=\"wp-image-95\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>這個課程是我和馬先生一同創作的心血結晶，緣起是他2018-19年在台灣的時候寫了一本書，叫做《藝術並非十一種玩意兒——藉由破除迷思進而揭露藝術的真正價值及重要性 （Eleven Things That Art is Not—— debunking the misconceptions to reveal the true value and importance of art）》，2020年上架到亞馬遜網站。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>這本書，我讀完後深受感動，於是自告奮勇將它翻譯成中文，想讓對藝術有興趣的台灣人也可以受惠。這裡補充一下我的相關背景，我畢業於東吳英文系，畢業之後斜槓口譯、筆譯與編輯工作至今超過15年，書面處理過大約325萬字。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>總之，緣份之下接到一位好友邀請，得知「Joy to Know 就去學」提供了我們一個分享的平台，於是依照其課程架構，擷取了書中部分內容，錄製成一個大約50分鐘的線上講座，分為五堂課、一堂10分鐘左右，希望藉由知識的分享，讓有興趣的人能夠更瞭解藝術。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>今天跟大家分享，提供給就去學知識平台的其中一段書中內容。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>為什麼許多藝術家的作品名為《無題》呢？</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>西元 1550 年，喬治．瓦薩里獻給佛羅倫斯公爵的《藝苑名人傳》，是一部共有十冊的藝術史巨作，除了詳細記述了藝術家們的生活，也討論了藝術家的作品和發表了評論，值得注意的是，他使用內容、地點或作品特徵的方式來指稱作品，而非作品的名稱。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>這是因為，在當時，作品根本沒有名稱。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>從古典樂時期流傳下來的傳統是，作曲家只為他所編寫的曲目標上數字以供區分。大名鼎鼎的作品，達文西的《蒙娜麗莎》、貝多芬的《月光奏鳴曲》，創作者本人都不是這麼命名，這些名稱皆為其他人後來冠上。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>事實上，為作品命名完全是現代才有的事，不確定從何時何處開始，直到今日，藝術品的名字，仍然相當普遍地由藝廊老闆、館長、評論家或贊助商來定，而非藝術家本人。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>追尋這項發展背後可能的原因，我們從惠斯勒最有名的畫作《惠斯勒的母親》中可一窺端倪，至少，它後來的名稱為此。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>在 1871 年，倫敦皇家藝術學院本來要拒絕展出這幅作品，因為當時呈交的名稱為「灰與黑的排列組合」。普羅大眾和學院成員都想要一個更具描述性的名稱，所以惠斯勒為了展覽被迫取了一個副標題「藝術家母親之肖像」。由此，逐漸演變成後來為人所知的稱謂。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>這讓人不禁疑問，名稱真的如此必要嗎？</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>如果畫家畫了一隻貓，把這幅畫稱作《貓》，好像沒什麼意義。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>惠斯勒在 1890 年寫出了《灰與黑的排列組合》事件帶給他的困惑：「對我來說，那幅我母親的畫作非常有意思；但對大眾而言，他們幹嘛要、也怎麼會在乎那幅肖像畫的是誰？」</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>我們常常在美術館或博物館裡看到一群人，熱切地看著聽著導覽人員，甚至比他們看展覽品的時間還多。展覽廳可能空蕩蕩，但藝術家訪談的影片總是圍繞著一群觀眾。當被問及何以如此，常常得到的回答是，如果不知道作品名稱或相關資料擔心會看不懂。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>然而，藝術家們已經不知說過多少次，談論藝術是沒有用的：</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>「畫作中最有價值的部分，正是無法以言語描述出來的部分。」——喬治．布拉克</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>「試著解釋一幅畫的人，通常都挑錯重點了。」——巴勃羅．畢卡索</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>「如果你講的出來，幹嘛還要畫？」、「談論一幅畫是沒有用的——一個人永遠講不出來，他只能在周圍繞圈圈。」——法蘭西斯．培根</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>一件藝術品能夠獨當一面；它不需要任何解釋。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>況且，當你在處理藝術這個主題的時候，你在處理的是高於語言的媒介。我們在談的不只是繪畫：「在 20 世紀以前，大家都認為作家已經把他想說的全都寫在他的作品裡了。」——約翰．厄普代克</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>一段純粹的音樂是抽象的。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>要說一個人能夠口頭詮釋它的意思，是很奇怪的概念。要為這些音符組合加上一個名字局限在一個代表，是更奇怪的一件事，因為之前沒有名字時，反而擁有天馬行空的無限自由。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>下次，當你去看一幅畫作時，不要顧著拍照，不要和朋友聊天，不要戴上耳機或做任何事情，試著保持安靜、靜止，真正地去看那幅畫，只要去體驗、感受它，花點時間。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>如果它帶你到了某種境界，讓它帶領，看看你是否喜歡，或是否覺得有趣。強烈的藝術體驗，可能會產生一種「浩瀚的感受」——彷彿「與一切合而為一」。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>藝術家能帶領人們啟航——不只是將人們從泥濘中扶起，而是帶領他們航向星際。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><img height=\"16\" width=\"16\" alt=\"👉\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t51/1/16/1f449.png\">如果你對藝術這個主題也有興趣，歡迎來上【美術老師沒教的藝術欣賞課】線上音頻課程。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><img height=\"16\" width=\"16\" alt=\"🚩\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tc6/1/16/1f6a9.png\">免費試聽第一堂：<a href=\"https://reurl.cc/VLgWxN?fbclid=IwZXh0bgNhZW0CMTAAAR0sibRX4ZlHv-aepuZ9GxctKEibyzChOhKFgMiBnk1DmCJCwYA8SYlSP54_aem_9jgQd42k8BNr3-oNu7HM7w\" rel=\"noreferrer noopener\" target=\"_blank\">https://reurl.cc/VLgWxN</a></p>\n<!-- /wp:paragraph -->', '【美術老師沒教的藝術欣賞課】線上音頻課程', '', 'inherit', 'closed', 'closed', '', '94-revision-v1', '', '', '2025-03-10 19:50:24', '2025-03-10 19:50:24', '', 94, 'http://localhost/chi-website/?p=96', 0, 'revision', '', 0),
(97, 1, '2025-03-10 19:55:28', '2025-03-10 19:55:28', '', 'Stanhope painting', '', 'inherit', 'open', 'closed', '', 'stanhope-painting-2', '', '', '2025-03-10 19:55:28', '2025-03-10 19:55:28', '', 55, 'http://localhost/chi-website/wp-content/uploads/2025/03/Stanhope-painting.jpg', 0, 'attachment', 'image/jpeg', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(98, 1, '2025-03-10 19:57:30', '2025-03-10 19:57:30', '<!-- wp:image {\"id\":39,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/Stanhope-painting.jpg\" alt=\"\" class=\"wp-image-39\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>這次在英國的普利茅斯，也去了博物館（The Box），還有一間新的藝廊以及一間展示本地藝術家作品的酒館（Manor Street Galleries）。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>出乎意料的發現博物館裡有一些透納的素描和草圖，但整間博物館裡我們覺得最精彩的一幅，是另一位英國畫家 Stanhope Alexander Forbes 的這幅作品（見上圖），當然照片只能傳達概念，如果有機會前去，找找這幅油畫。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>另外 Manor Street Galleries 裡頭，也有幾幅有趣的作品，而且價格相較於藝廊平易近人許多，也推薦給想要支持藝術家或想要家裡有藝術品的人 (見下圖)。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/Manor-Street-Galleries.jpg\" alt=\"\" class=\"wp-image-40\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:gallery {\"linkTo\":\"none\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><!-- wp:image {\"id\":41,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/Manor-Street-Galleries-2-.jpg\" alt=\"\" class=\"wp-image-41\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'The Box 博物館', '', 'inherit', 'closed', 'closed', '', '38-revision-v1', '', '', '2025-03-10 19:57:30', '2025-03-10 19:57:30', '', 38, 'http://localhost/chi-website/?p=98', 0, 'revision', '', 0),
(99, 1, '2025-03-10 20:01:47', '2025-03-10 20:01:47', '<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\">在威尼斯的時候，參觀了這間「佛圖尼博物館 （Museo Fortuny）」，因為受到建築本身空間規劃的吸引，博物館前身就是藝術家佛圖尼（Mariano Fortuny）本人的住宅，裡頭有他的畫室、織物研究室等，陳列許多畫作、織料和雕塑。<br>而在一樓的冬令花園（The Winter Garden）房，幾面牆上滿滿的壁畫，讓我聯想到毛姆寫的《月亮與六便士》裡最後藝術家的鉅作，有種發自內心的感動。<br>最後還有一個令人意想不到的驚喜，在參觀動線的尾端，有一座迴廊，細緻的工藝搭配精心的照明，當我發現它是由「瓦愣紙」雕築而成時，我驚嘆地重新來回走了好幾遍，想看清楚每個被我忽略的小細節。<br>推薦給要去威尼斯旅行的朋友，這間獨樹一格的博物館。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":21,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/IMG_99421.jpg\" alt=\"\" class=\"wp-image-21\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":20,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/IMG_99351.jpg\" alt=\"\" class=\"wp-image-20\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":19,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/IMG_99341-1.jpg\" alt=\"\" class=\"wp-image-19\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":22,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/IMG_99321.jpg\" alt=\"\" class=\"wp-image-22\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":23,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/IMG_99471.jpg\" alt=\"\" class=\"wp-image-23\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":24,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/IMG_99511.jpg\" alt=\"\" class=\"wp-image-24\"/></figure>\n<!-- /wp:image -->', '佛圖尼博物館 （Museo Fortuny）', '', 'inherit', 'closed', 'closed', '', '5-autosave-v1', '', '', '2025-03-10 20:01:47', '2025-03-10 20:01:47', '', 5, 'http://localhost/chi-website/?p=99', 0, 'revision', '', 0),
(100, 1, '2025-03-10 20:03:10', '2025-03-10 20:03:10', '<!-- wp:image {\"id\":39,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/Stanhope-painting.jpg\" alt=\"\" class=\"wp-image-39\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>這次在英國的普利茅斯，也去了博物館（The Box），還有一間新的藝廊以及一間展示本地藝術家作品的酒館（Manor Street Galleries）。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>出乎意料的發現博物館裡有一些透納的素描和草圖，但整間博物館裡我們覺得最精彩的一幅，是另一位英國畫家 Stanhope Alexander Forbes 的這幅作品（見上圖），當然照片只能傳達概念，如果有機會前去，找找這幅油畫。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>另外 Manor Street Galleries 裡頭，也有幾幅有趣的作品，而且價格相較於藝廊平易近人許多，也推薦給想要支持藝術家或想要家裡有藝術品的人 (見下圖)。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/Manor-Street-Galleries.jpg\" alt=\"\" class=\"wp-image-40\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:gallery {\"linkTo\":\"none\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><!-- wp:image {\"id\":41,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/02/Manor-Street-Galleries-2-.jpg\" alt=\"\" class=\"wp-image-41\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', '普利茅斯 - The Box 博物館', '', 'inherit', 'closed', 'closed', '', '38-revision-v1', '', '', '2025-03-10 20:03:10', '2025-03-10 20:03:10', '', 38, 'http://localhost/chi-website/?p=100', 0, 'revision', '', 0),
(101, 1, '2025-03-10 20:11:35', '2025-03-10 20:11:35', '<!-- wp:image {\"id\":102,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/威爾斯火車.jpg\" alt=\"\" class=\"wp-image-102\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>英國的火車票有很多種，其中「當日票（Anytime Day ticket）」在起站和終站間可以當天不限時間和次數地出站和進站，例如：從城市A要到城市D，可以在中間經過的小鎮B和小鎮C自由出站再進站，也就是說如果行程安排的好，可以一票玩好幾個城鎮。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a></a>不過，當日票不見得便宜，有時候從A地到D地限定時間和車廂類型的票會比較划算。儘管如此，還是提供一份資訊，讓行程規劃多一份選擇。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>上圖是威爾斯的火車，車上有充電插座和USB插孔；下圖一圈起來的地方寫的是「單日票/單程」；下圖二圈起來的地方就是在解釋單日票的使用彈性。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":103,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/火車票1.jpg\" alt=\"\" class=\"wp-image-103\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":104,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/火車票2.jpg\" alt=\"\" class=\"wp-image-104\"/></figure>\n<!-- /wp:image -->', '英國火車當日票優點', '', 'publish', 'open', 'open', '', '%e8%8b%b1%e5%9c%8b%e7%81%ab%e8%bb%8a%e7%95%b6%e6%97%a5%e7%a5%a8%e5%84%aa%e9%bb%9e', '', '', '2025-03-10 20:11:35', '2025-03-10 20:11:35', '', 0, 'http://localhost/chi-website/?p=101', 0, 'post', '', 0),
