(106, 1, '2025-03-10 20:13:58', '2025-03-10 20:13:58', '<!-- wp:navigation-submenu {\"label\":\"威爾斯自由行\",\"type\":\"page\",\"id\":29,\"url\":\"http://localhost/chi-website/%E9%97%9C%E6%96%BC%E5%B0%8F%E7%90%AA/\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:navigation-submenu {\"label\":\"英國自由行\",\"url\":\"%E8%8B%B1%E6%A0%BC%E8%98%AD%E8%87%AA%E7%94%B1%E8%A1%8C\",\"kind\":\"custom\"} -->\n<!-- wp:navigation-link {\"label\":\"英國火車當日票優點\",\"type\":\"post\",\"id\":101,\"url\":\"http://localhost/chi-website/2025/03/10/%E8%8B%B1%E5%9C%8B%E7%81%AB%E8%BB%8A%E7%95%B6%E6%97%A5%E7%A5%A8%E5%84%AA%E9%BB%9E/\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"普利茅斯 – The Box 博物館\",\"type\":\"post\",\"id\":38,\"url\":\"http://localhost/chi-website/2025/02/27/%E8%8B%B1%E5%9C%8B%E6%99%AE%E5%88%A9%E8%8C%85%E6%96%AF%E7%9A%84%E5%8D%9A%E7%89%A9%E9%A4%A8%EF%BC%8Dthe-box/\",\"kind\":\"post-type\"} /-->\n<!-- /wp:navigation-submenu -->\n\n<!-- wp:navigation-submenu {\"label\":\"義大利自由行\",\"type\":\"tag\",\"id\":5,\"url\":\"http://localhost/chi-website/tag/%E7%BE%A9%E5%A4%A7%E5%88%A9%E8%87%AA%E7%94%B1%E8%A1%8C/\",\"kind\":\"taxonomy\"} -->\n<!-- wp:navigation-link {\"label\":\"威尼斯－佛圖尼博物館 （Museo Fortuny）\",\"type\":\"post\",\"id\":5,\"url\":\"http://localhost/chi-website/2025/02/27/%E5%A8%81%E5%B0%BC%E6%96%AF%EF%BC%8D%E4%BD%9B%E5%9C%96%E5%B0%BC%E5%8D%9A%E7%89%A9%E9%A4%A8-%EF%BC%88museo-fortuny%EF%BC%89/\",\"kind\":\"post-type\"} /-->\n<!-- /wp:navigation-submenu -->\n\n<!-- wp:navigation-submenu {\"label\":\"亞洲自由行\",\"url\":\"%E6%AD%90%E6%B4%B2%E8%87%AA%E7%94%B1%E8%A1%8C\",\"kind\":\"custom\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"首頁\",\"type\":\"page\",\"id\":52,\"url\":\"http://localhost/chi-website/%E5%A8%81%E7%88%BE%E6%96%AF%E9%A6%96%E9%83%BD%E5%8D%A1%E5%9C%B0%E5%A4%AB/\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"關於小琪\",\"type\":\"page\",\"id\":29,\"url\":\"http://localhost/chi-website/%e9%97%9c%e6%96%bc%e5%b0%8f%e7%90%aa/\",\"kind\":\"post-type\"} /-->', 'Navigation', '', 'inherit', 'closed', 'closed', '', '4-revision-v1', '', '', '2025-03-10 20:13:58', '2025-03-10 20:13:58', '', 4, 'http://localhost/chi-website/?p=106', 0, 'revision', '', 0),
(107, 1, '2025-03-10 20:19:26', '2025-03-10 20:19:26', '<!-- wp:image {\"id\":108,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/villa-Necchi-camiglio.jpg\" alt=\"\" class=\"wp-image-108\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>去米蘭前在規劃行程的時候，發現除了米蘭大教堂，有幾間前身為私人寓所、後開放成為博物館的地方我也想去看看，於是買了一張「豪宅博物館卡（Case Museo Card）」，參觀了米蘭的四間豪宅博物館，大飽眼福也大開眼界。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a></a>照片是其中一間博物館——「內基·坎皮格里奧別墅 （Villa Necchi Campiglio）」裡頭讓我最爲傾倒的設計。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>這間博物館的門票，一般成人單買一張15歐，但博物館卡（Case Museo Card）只要25歐（約台幣880），自購買日起一年內可以參觀四間博物館各一次。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>博物館的介紹和博物館卡的購買都在下面官網裡</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:embed {\"url\":\"https://casemuseo.it/en/la-card-eng/\",\"type\":\"wp-embed\",\"providerNameSlug\":\"case-museo-di-milano\"} -->\n<figure class=\"wp-block-embed is-type-wp-embed is-provider-case-museo-di-milano wp-block-embed-case-museo-di-milano\"><div class=\"wp-block-embed__wrapper\">\nhttps://casemuseo.it/en/la-card-eng/\n</div></figure>\n<!-- /wp:embed -->', '內基·坎皮格里奧別墅 （Villa Necchi Campiglio）', '', 'publish', 'open', 'open', '', '%e5%85%a7%e5%9f%ba%c2%b7%e5%9d%8e%e7%9a%ae%e6%a0%bc%e9%87%8c%e5%a5%a7%e5%88%a5%e5%a2%85-%ef%bc%88villa-necchi-campiglio%ef%bc%89', '', '', '2025-03-10 20:19:26', '2025-03-10 20:19:26', '', 0, 'http://localhost/chi-website/?p=107', 0, 'post', '', 0),
