s-style-section-1\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--80)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|80\",\"left\":\"var:preset|spacing|80\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"45%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-right:var(--wp--preset--spacing--50);flex-basis:45%\"><!-- wp:image {\"sizeSlug\":\"full\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/themes/twentytwentyfive/assets/images/red-hibiscus-closeup.webp\" alt=\"紅花特寫攝影。\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"-12vw\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:-12vw\"><!-- wp:image {\"width\":\"202px\",\"sizeSlug\":\"full\",\"align\":\"right\",\"className\":\"is-resized\",\"style\":{\"spacing\":{\"margin\":{\"right\":\"-5vw\",\"left\":\"-5vw\"}}}} -->\n<figure class=\"wp-block-image alignright size-full is-resized\" style=\"margin-right:-5vw;margin-left:-5vw\"><img src=\"http://localhost/chi-website/wp-content/themes/twentytwentyfive/assets/images/grid-flower-2.webp\" alt=\"花朵特寫的黑白攝影。\" style=\"width:202px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\",\"style\":{\"spacing\":{\"padding\":{\"left\":\"0\",\"right\":\"0\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-right:0;padding-left:0;flex-basis:50%\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"className\":\"is-style-text-annotation\"} -->\n<h2 class=\"wp-block-heading is-style-text-annotation\">關於我們</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"className\":\"is-style-text-subtitle\"} -->\n<p class=\"is-style-text-subtitle\">\n			<strong>Fleurs</strong> 是一家總部設於歐盟，提供鮮花配送及客戶定期回購服務的公司。我們的使名不僅是配送令人驚艷的插花作品，更要培養大眾對大自然美麗獻禮 - 花朵的知識及熱愛。			</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"blockGap\":\"var:preset|spacing|50\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50)\"><!-- wp:heading {\"align\":\"wide\"} -->\n<h2 class=\"wp-block-heading alignwide\">我們的服務項目</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"aspectRatio\":\"4/3\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"24px\"}}}} -->\n<figure class=\"wp-block-image size-full\" style=\"margin-bottom:24px\"><img src=\"http://localhost/chi-website/wp-content/themes/twentytwentyfive/assets/images/campanula-alliariifolia-flower.webp\" alt=\"服務圖片\" style=\"aspect-ratio:4/3;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">收購花卉</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">如同在意料之外的地方盛開的花朵，每個故事都以美麗和堅韌的姿態展開</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"aspectRatio\":\"4/3\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"24px\"}}}} -->\n<figure class=\"wp-block-image size-full\" style=\"margin-bottom:24px\"><img src=\"http://localhost/chi-website/wp-content/themes/twentytwentyfive/assets/images/delphinium-flowers.webp\" alt=\"服務圖片\" style=\"aspect-ratio:4/3;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">花藝設計</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">如同在意料之外的地方盛開的花朵，每個故事都以美麗和堅韌的姿態展開</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"aspectRatio\":\"4/3\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"24px\"}}}} -->\n<figure class=\"wp-block-image size-full\" style=\"margin-bottom:24px\"><img src=\"http://localhost/chi-website/wp-content/themes/twentytwentyfive/assets/images/star-thristle-flower.webp\" alt=\"服務圖片\" style=\"aspect-ratio:4/3;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">商品配送</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">如同在意料之外的地方盛開的花朵，每個故事都以美麗和堅韌的姿態展開</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"blockGap\":\"var:preset|spacing|60\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"left\",\"flexWrap\":\"wrap\",\"verticalAlignment\":\"space-between\"}} -->\n<div class=\"wp-block-group\" style=\"min-height:100%\"><!-- wp:heading {\"className\":\"is-style-text-annotation\",\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}},\"fontSize\":\"x-small\"} -->\n<h2 class=\"wp-block-heading is-style-text-annotation has-x-small-font-size\">大家在討論的話題</h2>\n<!-- /wp:heading -->\n\n<!-- wp:quote {\"className\":\"is-style-plain\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|50\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"x-large\"} -->\n<blockquote class=\"wp-block-quote is-style-plain has-x-large-font-size\" style=\"font-style:normal;font-weight:400\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\",\"contentSize\":\"400px\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:paragraph {\"fontSize\":\"xx-large\"} -->\n<p class=\"has-xx-large-font-size\">“一流的商品及客戶服務！”</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --><cite>木藍裘<br><sub>嘉義縣民雄鄉</sub></cite></blockquote>\n<!-- /wp:quote --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:image {\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/chi-website/wp-content/themes/twentytwentyfive/assets/images/typewriter.webp\" alt=\"某個人在使用打字機打字的圖片。\" style=\"aspect-ratio:1;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\"><!-- wp:heading {\"textAlign\":\"center\",\"align\":\"wide\"} -->\n<h2 class=\"wp-block-heading alignwide has-text-align-center\">方案價格</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">隨時都可以取消或暫停。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\"} -->\n<div style=\"height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\"}},\"border\":{\"width\":\"1px\",\"color\":\"var:preset|color|accent-6\",\"radius\":\"10px\"}}} -->\n<div class=\"wp-block-column has-border-color\" style=\"border-color:var(--wp--preset--color--accent-6);border-width:1px;border-radius:10px;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\" id=\"free\">免費方案</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">NTD 0</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-checkmark-list\",\"style\":{\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}},\"fontSize\":\"small\"} -->\n<ul style=\"padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\" class=\"wp-block-list is-style-checkmark-list has-small-font-size\"><!-- wp:list-item -->\n<li>可閱讀我們撰寫的付費文章及每週寄送的電子報。</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>參加 IRL 活動。</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>可獲得免費的托特包。</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>居家裝飾系列中的雅致之選。</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>加入我們的官方論壇。</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"width\":100} -->\n<div class=\"wp-block-button has-custom-width wp-block-button__width-100\"><a class=\"wp-block-button__link wp-element-button\">加入</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\"}},\"border\":{\"width\":\"1px\",\"color\":\"var:preset|color|accent-6\",\"radius\":\"10px\"}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column has-border-color\" style=\"border-color:var(--wp--preset--color--accent-6);border-width:1px;border-radius:10px;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\" id=\"single\">個人方案</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">NTD 700/月</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-checkmark-list\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}},\"fontSize\":\"small\"} -->\n<ul style=\"padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\" class=\"wp-block-list is-style-checkmark-list has-small-font-size\"><!-- wp:list-item -->\n<li>可閱讀我們撰寫的付費文章及每週寄送的電子報。</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>參加 IRL 活動。</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>可獲得免費的托特包。</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>居家裝飾系列中的雅致之選。</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>加入我們的官方論壇。</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"width\":100} -->\n<div class=\"wp-block-button has-custom-width wp-block-button__width-100\"><a class=\"wp-block-button__link wp-element-button\">加入</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"aside\",\"align\":\"full\",\"className\":\"is-style-section-3\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"dimensions\":{\"minHeight\":\"\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"800px\"}} -->\n<aside class=\"wp-block-group alignfull is-style-section-3\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"360px\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\" style=\"min-height:360px;margin-top:0;margin-bottom:0\"><!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"xx-large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-xx-large-font-size\">註冊以獲得每日故事選輯</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"is-style-text-subtitle\"} -->\n<p class=\"has-text-align-center is-style-text-subtitle\">獲得以歷史照片為特色的精彩瞬間照片集。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"20px\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"textAlign\":\"center\"} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-center wp-element-button\">訂閱</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></aside>\n<!-- /wp:group -->', '', '', 'inherit', 'closed', 'closed', '', '110-autosave-v1', '', '', '2025-03-10 20:37:49', '2025-03-10 20:37:49', '', 110, 'http://localhost/chi-website/?p=115', 0, 'revision', '', 0),
