(949, 1, '2025-03-12 20:11:36', '2025-03-12 20:11:36', '<!-- wp:image {\"id\":950,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/royal-arcade-cardiff.jpg\" alt=\"\" class=\"wp-image-950\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>到有「拱廊之都（City of Arcades）」的卡地夫，再怎麼匆忙還是要逛一下拱廊，這一條Royal Arcade是卡地夫最古老的拱廊，自1858年存在至今。</p>\n<!-- /wp:paragraph -->', '首都  卡地夫（Cardiff）', '', 'publish', 'open', 'open', '', '%e9%a6%96%e9%83%bd%ef%bc%8d%e5%8d%a1%e5%9c%b0%e5%a4%ab', '', '', '2026-01-07 15:38:24', '2026-01-07 15:38:24', '', 0, 'http://localhost/chi-website/?p=949', 0, 'post', '', 0),
