', '', 0),
(1119, 1, '2025-03-21 17:59:40', '2025-03-21 17:59:40', '<!-- wp:image {\"id\":1120,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/紅鳶.jpg\" alt=\"\" class=\"wp-image-1120\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>在中威爾斯的Rhayader小鎮設有一處「紅鳶（ㄩㄢˉ）餵食站（Red Kite Feeding Station）」，我們這一趟也買了票去參觀。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>在1900年左右，紅鳶這個物種差點滅絕，只剩下三對，因為當時歐洲流行打獵和蒐集鳥蛋，經過一百多年的保育和復育，現在總共有兩百多隻，而且全都是同一對紅鳶的後代。以上資訊得自於前一天的「威爾斯國家洞穴展示中心」，覺得很不可思議！</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>威爾斯有好幾處紅鳶保育、餵食農場，可以讓愛鳥人士近距離觀察到紅鳶，不同金額的門票也能為復育紅鳶盡一份心力。有機會來威爾斯，歡迎去看紅鳶！</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":1121,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/紅鳶1.jpg\" alt=\"\" class=\"wp-image-1121\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:image {\"id\":1122,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/紅鳶觀察站.jpg\" alt=\"\" class=\"wp-image-1122\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":1123,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/紅鳶觀察站2.jpg\" alt=\"\" class=\"wp-image-1123\"/></figure>\n<!-- /wp:image -->', '紅鳶（ㄩㄢˉ）餵食站', '', 'publish', 'open', 'open', '', '%e7%b4%85%e9%b3%b6%ef%bc%88%e3%84%a9%e3%84%a2%cb%89%ef%bc%89%e9%a4%b5%e9%a3%9f%e7%ab%99', '', '', '2025-03-21 17:59:40', '2025-03-21 17:59:40', '', 0, 'http://localhost/chi-website/?p=1119', 0, 'post', '', 0),
