(1124, 1, '2025-03-21 17:59:40', '2025-03-21 17:59:40', '<!-- wp:image {\"id\":1120,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/紅鳶.jpg\" alt=\"\" class=\"wp-image-1120\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>在中威爾斯的Rhayader小鎮設有一處「紅鳶（ㄩㄢˉ）餵食站（Red Kite Feeding Station）」，我們這一趟也買了票去參觀。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>在1900年左右，紅鳶這個物種差點滅絕，只剩下三對，因為當時歐洲流行打獵和蒐集鳥蛋，經過一百多年的保育和復育，現在總共有兩百多隻，而且全都是同一對紅鳶的後代。以上資訊得自於前一天的「威爾斯國家洞穴展示中心」，覺得很不可思議！</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>威爾斯有好幾處紅鳶保育、餵食農場，可以讓愛鳥人士近距離觀察到紅鳶，不同金額的門票也能為復育紅鳶盡一份心力。有機會來威爾斯，歡迎去看紅鳶！</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":1121,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/紅鳶1.jpg\" alt=\"\" class=\"wp-image-1121\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:image {\"id\":1122,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/紅鳶觀察站.jpg\" alt=\"\" class=\"wp-image-1122\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":1123,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/紅鳶觀察站2.jpg\" alt=\"\" class=\"wp-image-1123\"/></figure>\n<!-- /wp:image -->', '紅鳶（ㄩㄢˉ）餵食站', '', 'inherit', 'closed', 'closed', '', '1119-revision-v1', '', '', '2025-03-21 17:59:40', '2025-03-21 17:59:40', '', 1119, 'http://localhost/chi-website/?p=1124', 0, 'revision', '', 0),
(1127, 1, '2025-03-21 18:27:22', '2025-03-21 18:27:22', '<!-- wp:image {\"id\":1128,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/Elan-valley.jpg\" alt=\"\" class=\"wp-image-1128\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>中威爾斯旅行的第二天我們去了伊嵐谷（Elan Valley），讚嘆一整路。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>伊嵐谷是位於中威爾斯的一座河谷，因其風景如畫而有「威爾斯湖區（Welsh Lake District）」的別名，其範圍達 70 平方英里（180 平方公里），裡頭包含湖泊和鄉村和一條受歡迎的自行車道——伊嵐谷小徑 (Elan Valley Trail) ，該小徑的一部分與 81 號國家自行車道 (Lon Cambria) 的支線重疊。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>伊嵐谷於2015年入選成為了「國際黑暗天空公園（International Dark Sky Park）」。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":1129,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/Elan-valley-1.jpg\" alt=\"\" class=\"wp-image-1129\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":1130,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/elan-valley-2.jpg\" alt=\"\" class=\"wp-image-1130\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":1131,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/elan-valley-3.jpg\" alt=\"\" class=\"wp-image-1131\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":1132,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/elan-valley-4.jpg\" alt=\"\" class=\"wp-image-1132\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":1133,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/elan-valley-6.jpg\" alt=\"\" class=\"wp-image-1133\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":1134,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/elan-valley-7.jpg\" alt=\"\" class=\"wp-image-1134\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":1135,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/elan-valley-5.jpg\" alt=\"\" class=\"wp-image-1135\"/></figure>\n<!-- /wp:image -->', '伊嵐谷（Elan Valley）', '', 'publish', 'open', 'open', '', '%e4%bc%8a%e5%b5%90%e8%b0%b7%ef%bc%88elan-valley%ef%bc%89', '', '', '2025-03-21 20:26:49', '2025-03-21 20:26:49', '', 0, 'http://localhost/chi-website/?p=1127', 0, 'post', '', 0),
