(1151, 1, '2026-01-07 15:38:24', '2026-01-07 15:38:24', '<!-- wp:image {\"id\":950,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/chi-website/wp-content/uploads/2025/03/royal-arcade-cardiff.jpg\" alt=\"\" class=\"wp-image-950\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>到有「拱廊之都（City of Arcades）」的卡地夫，再怎麼匆忙還是要逛一下拱廊，這一條Royal Arcade是卡地夫最古老的拱廊，自1858年存在至今。</p>\n<!-- /wp:paragraph -->', '首都  卡地夫（Cardiff）', '', 'inherit', 'closed', 'closed', '', '949-revision-v1', '', '', '2026-01-07 15:38:24', '2026-01-07 15:38:24', '', 949, 'http://localhost/chi-website/?p=1151', 0, 'revision', '', 0);
